 partial class Studio {
  Study currentStudy;DataGridView checks=new DataGridView(),results=new DataGridView();TextBox memory=new TextBox();Label studySummary=new Label();TabPage studyPage;int revision,lastAutosave=-1;System.Windows.Forms.Timer autosave;
  static string userData=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"OpenEletric");
  FlowLayoutPanel BuildTools(){
   var tools=new FlowLayoutPanel{WrapContents=false};AddButton(tools,"Fonte",EditSource,90);AddButton(tools,"Conectar",ConnectBoard,105);AddButton(tools,"Catálogo",OpenCatalog,90);AddButton(tools,"Cabos",SelectCable,85);AddButton(tools,"Frontal",OpenEnclosure,80);AddButton(tools,"Curvas",OpenCurves,80);
   studyPage=new TabPage("Estudos");var studyLayout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3};studyLayout.RowStyles.Add(new RowStyle(SizeType.Absolute,75));studyLayout.RowStyles.Add(new RowStyle(SizeType.Percent,45));studyLayout.RowStyles.Add(new RowStyle(SizeType.Percent,55));studySummary.Dock=DockStyle.Fill;studySummary.Padding=new Padding(10);studySummary.BackColor=Color.FromArgb(232,244,244);studySummary.ForeColor=navy;
   ConfigureGrid(results);foreach(string col in new[]{"Circuito","Quadro","Ib (A)","Queda (%)","Acum. (%)","Ik 3F origem","Ik 3F fim","Ik 2F aprox. origem","Ik 2F aprox. fim","I laço terra","Iz (A)"})results.Columns.Add(col,col);results.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.None;results.ScrollBars=ScrollBars.Both;int[] resultWidths={180,115,65,78,78,88,88,112,112,92,65};for(int n=0;n<resultWidths.Length;n++)results.Columns[n].Width=resultWidths[n];
   ConfigureGrid(checks);foreach(string col in new[]{"Circuito","Verificação","Resultado","Detalhe"})checks.Columns.Add(col,col);checks.Columns[1].FillWeight=200;checks.Columns[3].FillWeight=340;
   results.SelectionChanged+=(s,e)=>{if(sync||results.SelectedRows.Count==0)return;var c=results.SelectedRows[0].Tag as Circuit;if(c!=null){circuit=c;board=project.Boards.First(b=>b.Circuits.Contains(c));properties.SelectedObject=c;}};
   studyLayout.Controls.Add(studySummary,0,0);studyLayout.Controls.Add(results,0,1);studyLayout.Controls.Add(checks,0,2);studyPage.Controls.Add(studyLayout);tabs.TabPages.Add(studyPage);
   var memo=new TabPage("Memória de cálculo");memory.Dock=DockStyle.Fill;memory.Multiline=true;memory.ReadOnly=true;memory.WordWrap=false;memory.ScrollBars=ScrollBars.Both;memory.Font=new Font("Consolas",10);memory.BackColor=Color.White;memo.Controls.Add(memory);tabs.TabPages.Add(memo);
   var extra=new ContextMenuStrip();extra.Items.Add("Intercâmbio AMB / DXF / prévia",null,(s,e)=>Safe(OpenDxfInterchange));extra.Items.Add("Relatório por seleção",null,(s,e)=>Safe(()=>{using(var form=new ReportSelectionForm(project))form.ShowDialog(this);}));extra.Items.Add("Prévia / impressão / PDF",null,(s,e)=>Safe(()=>ReportPrinting.Preview(project,this)));extra.Items.Add("Relatório RTF",null,(s,e)=>Safe(ExportRtf));extra.Items.Add("Recuperar projeto / backup",null,(s,e)=>Safe(Recover));extra.Items.Add("Forma de onda de curto R-L",null,(s,e)=>Safe(()=>{if(board==null||circuit==null)throw new InvalidOperationException("Selecione um circuito.");using(var form=new FaultWaveformForm(project,board,circuit))form.ShowDialog(this);}));extra.Items.Add("Memória de cálculo TXT",null,(s,e)=>Safe(ExportMemory));extra.Items.Add("Lista de materiais CSV",null,(s,e)=>Safe(ExportMaterials));extra.Items.Add("Distribuir fases L1/L2/L3",null,(s,e)=>Safe(BalancePhases));extra.Items.Add("Adicionar banco de capacitores",null,(s,e)=>Safe(AddCapacitor));extra.Items.Add("Invólucro real / frontalDIN",null,(s,e)=>Safe(ConfigureEnclosureCatalog));extra.Items.Add("Barras / busway do quadro",null,(s,e)=>Safe(ConfigureBusbars));extra.Items.Add("Histórico temporal importado",null,(s,e)=>Safe(ConfigureFaultTimeTrace));extra.Items.Add("Extremos3F/LL e fontes",null,(s,e)=>Safe(ConfigureFaultExtremes));extra.Items.Add("Fluxo por fase e neutro",null,(s,e)=>Safe(ConfigureNetworkFlow));extra.Items.Add("Contato e tempo de desligamento",null,(s,e)=>Safe(ConfigureContactTime));extra.Items.Add("Laços de falta N/PE/PEN e IT",null,(s,e)=>Safe(ConfigureFaultLoops));extra.Items.Add("Dimensionar neutro, PE e PEN",null,(s,e)=>Safe(ConfigureReturnSizing));extra.Items.Add("Aterramento e condutores",null,(s,e)=>Safe(ConfigureGrounding));extra.Items.Add("Contator, partida e térmico",null,(s,e)=>Safe(ConfigureMotorStarterSelection));extra.Items.Add("Diferenciais, relés e acessórios",null,(s,e)=>Safe(ConfigureResidualSelection));extra.Items.Add("Curvas t-I, I²t e Ip",null,(s,e)=>Safe(ConfigureProtectionResponses));extra.Items.Add("Fusíveis e seccionadores",null,(s,e)=>Safe(ConfigureSwitchgear));extra.Items.Add("Seletividade / backup por par",null,(s,e)=>Safe(ConfigureCoordination));extra.Items.Add("Método, edição e hipóteses",null,(s,e)=>Safe(ConfigureCalculationProfile));extra.Items.Add("Seleção de disjuntores",null,(s,e)=>Safe(ConfigureBreakerSelection));extra.Items.Add("Condições dos cabos",null,(s,e)=>Safe(ConfigureCableFactors));extra.Items.Add("Motor — rendimento e partida",null,(s,e)=>Safe(MotorLoad));extra.Items.Add("Inversor e motor associado",null,(s,e)=>Safe(ConfigureDriveMotor));extra.Items.Add("Licenças de componentes",null,(s,e)=>Safe(()=>EmbeddedComponents.ShowLicenses(this)));var more=new Button{Text="Ferramentas...",Height=34,Width=135,BackColor=Color.White,FlatStyle=FlatStyle.Flat};more.Click+=(s,e)=>extra.Show(more,new Point(0,more.Height));tools.Controls.Add(more);
   return tools;
  }
  void ConfigureGrid(DataGridView g){g.Dock=DockStyle.Fill;g.ReadOnly=true;g.AllowUserToAddRows=false;g.AllowUserToDeleteRows=false;g.RowHeadersVisible=false;g.MultiSelect=false;g.SelectionMode=DataGridViewSelectionMode.FullRowSelect;g.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;g.BackgroundColor=Color.White;g.BorderStyle=BorderStyle.None;g.DefaultCellStyle.Font=new Font("Segoe UI",9);g.RowTemplate.Height=32;g.DefaultCellStyle.WrapMode=DataGridViewTriState.True;g.AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells;}
  static string V(double? value){return value.HasValue?value.Value.ToString("N2"):"—";}
  void RefreshStudies(){
   if(currentStudy==null)return;sync=true;results.Rows.Clear();checks.Rows.Clear();foreach(var r in currentStudy.Circuits){int i=results.Rows.Add(r.Circuit.Id+" · "+r.Circuit.Name,r.Board.Name,r.CurrentA.ToString("N2"),r.VoltageDropKnown?r.VoltageDropPercent.ToString("N2"):"—",r.AccumulatedDropKnown?r.AccumulatedDropPercent.ToString("N2"):"—",V(r.FaultOriginKA),V(r.FaultEndKA),V(r.FaultTwoPhaseOriginKA),V(r.FaultTwoPhaseEndKA),V(r.FaultLoopKA),V(r.CorrectedAmpacityA));results.Rows[i].Tag=r.Circuit;}
   foreach(var check in currentStudy.Checks.OrderBy(c=>c.Status=="Falha"?0:c.Status=="Pendente"?1:2)){int i=checks.Rows.Add(check.CircuitId,check.Rule,check.Status,check.Detail);checks.Rows[i].Cells[2].Style.ForeColor=check.Status=="Falha"?Color.Firebrick:check.Status=="Pendente"?Color.DarkGoldenrod:Color.Teal;}
   sync=false;studySummary.Text=currentStudy.TotalKw.ToString("N2")+" kW de demanda  ·  "+currentStudy.TotalKvar.ToString("N2")+" kvar  ·  "+currentStudy.TotalKva.ToString("N2")+" kVA  ·  FP "+currentStudy.PowerFactor.ToString("N3")+"\nCorrente nominal por fase: "+(currentStudy.PhaseCurrentKnown?"L1 "+currentStudy.PhaseCurrentA[0].ToString("N2")+" A  ·  L2 "+currentStudy.PhaseCurrentA[1].ToString("N2")+" A  ·  L3 "+currentStudy.PhaseCurrentA[2].ToString("N2")+" A":"indisponível: tensões não correspondem à tensão de fonte")+"\nCompensação até FP "+project.Source.TargetPowerFactor+": "+currentStudy.CapacitorKvar.ToString("N2")+" kvar  ·  "+currentStudy.Checks.Count(c=>c.Status=="Falha")+" falhas  /  "+currentStudy.Checks.Count(c=>c.Status=="Pendente")+" pendências. Soma P/Q por fase; trifásico dividido igualmente. Sem harmônicas, neutro ou desequilíbrio de tensão.";memory.Text=EngineeringReport.Memory(project,currentStudy);
  }
  static T Clone<T>(T item){using(var m=new MemoryStream()){var serializer=new DataContractJsonSerializer(typeof(T));serializer.WriteObject(m,item);m.Position=0;return (T)serializer.ReadObject(m);}}
  void EditSource(){var original=project.Source;var copy=Clone(original);using(var d=new Form{Text="Alimentação e limites de estudo",Size=new Size(580,660),StartPosition=FormStartPosition.CenterParent}){var pg=new PropertyGrid{Dock=DockStyle.Fill,SelectedObject=copy,ToolbarVisible=false};var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48,FlowDirection=FlowDirection.RightToLeft};var ok=new Button{Text="Aplicar",Width=110,Height=32};ok.Click+=(s,e)=>{try{project.Source=copy;project.Validate();d.DialogResult=DialogResult.OK;}catch(Exception ex){project.Source=original;MessageBox.Show(ex.Message,"Verifique os dados");}};bottom.Controls.Add(ok);d.Controls.Add(pg);d.Controls.Add(bottom);if(d.ShowDialog(this)==DialogResult.OK){Change();tabs.SelectedTab=studyPage;}else project.Source=original;}}
  void ConnectBoard(){
   if(circuit==null)throw new InvalidOperationException("Selecione o circuito alimentador na tabela ou na árvore.");var candidates=project.Boards.Where(b=>b!=board).ToList();if(candidates.Count==0)throw new InvalidOperationException("Adicione outro quadro para conectar.");
   using(var d=new Form{Text="Conectar circuito a um quadro",ClientSize=new Size(455,185),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false}){
    var label=new Label{Text=circuit.Id+" · "+circuit.Name+" alimentará:",Location=new Point(20,20),Size=new Size(415,30)};var choices=new ComboBox{Location=new Point(20,55),Width=415,DropDownStyle=ComboBoxStyle.DropDownList};choices.Items.Add("Sem quadro vinculado");foreach(var b in candidates)choices.Items.Add(b);choices.SelectedIndex=0;for(int i=0;i<candidates.Count;i++)if(candidates[i].Id==circuit.ChildBoardId)choices.SelectedIndex=i+1;var apply=new Button{Text="Conectar",Location=new Point(300,115),Size=new Size(135,35)};
    apply.Click+=(s,e)=>{string old=circuit.ChildBoardId,kind=circuit.Kind,phase=circuit.PhaseLabel;double v=circuit.Voltage;PhaseMode mode=circuit.Phases;try{if(choices.SelectedIndex==0)circuit.ChildBoardId="";else{var target=(Board)choices.SelectedItem;circuit.ChildBoardId=target.Id;circuit.Phases=PhaseMode.Trifasico;circuit.Voltage=target.Voltage;circuit.PhaseLabel="ABC";circuit.Kind="Alimentador";}project.Validate();d.DialogResult=DialogResult.OK;}catch(Exception ex){circuit.ChildBoardId=old;circuit.Kind=kind;circuit.Phases=mode;circuit.Voltage=v;circuit.PhaseLabel=phase;MessageBox.Show(ex.Message);}};
    d.Controls.AddRange(new Control[]{label,choices,apply});if(d.ShowDialog(this)==DialogResult.OK)Change();
   }
  }
  void OpenCatalog(){Directory.CreateDirectory(userData);using(var d=new CatalogForm(Path.Combine(userData,"catalogo-v2.json"),project,circuit)){if(d.ShowDialog(this)!=DialogResult.OK||d.SelectedEquipment==null)return;if(circuit==null)throw new InvalidOperationException("Selecione primeiro um circuito para aplicar o equipamento.");CatalogApplication.Apply(circuit,d.SelectedEquipment);Change();}}
  void SelectCable(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito para pré-selecionar o cabo.");Directory.CreateDirectory(userData);using(var d=new CableSelectionForm(project,circuit,Path.Combine(userData,"cabos.csv"))){if(d.ShowDialog(this)!=DialogResult.OK||d.SelectedCable==null)return;var x=d.SelectedCable;circuit.CableMm2=x.SectionMm2;circuit.Cable.AmpacityA=x.IzA;circuit.Cable.ResistanceOhmKm=x.ResistanceOhmKm;circuit.Cable.ReactanceOhmKm=x.ReactanceOhmKm;circuit.Cable.Reference=x.Reference;circuit.Cable.InstallationMethod=x.Installation;circuit.Cable.Material=x.Material=="Copper"||x.Material=="Cu"?ConductorMaterial.Copper:ConductorMaterial.Aluminium;circuit.Cable.Insulation=x.Insulation=="PVC"?CableInsulation.PVC:CableInsulation.XLPE;Change();tabs.SelectedTab=studyPage;}}
  void OpenEnclosure(){if(board==null)throw new InvalidOperationException("Selecione um quadro.");using(var d=new EnclosureForm(project,board,Change))d.ShowDialog(this);}
  void OpenCurves(){if(board==null||circuit==null)throw new InvalidOperationException("Selecione um circuito para comparar curvas.");using(var d=new CurvesForm(project,board,circuit,Change))d.ShowDialog(this);}
  void ExportMemory(){using(var d=new SaveFileDialog{Filter="Texto (*.txt)|*.txt",FileName=SafeName(project.Name)+"-memoria.txt",InitialDirectory=Folder()})if(d.ShowDialog()==DialogResult.OK)File.WriteAllText(d.FileName,EngineeringReport.Memory(project,Engineering.Analyze(project)),new UTF8Encoding(true));}
  void ExportMaterials(){using(var d=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName=SafeName(project.Name)+"-materiais.csv",InitialDirectory=Folder()})if(d.ShowDialog()==DialogResult.OK)EngineeringReport.Materials(project,d.FileName);}
  string RecoveryFile(){Directory.CreateDirectory(Path.Combine(userData,"recuperacao"));string key=(currentFile??"Novo")+"|"+project.Name;using(var hash=SHA256.Create())return Path.Combine(userData,"recuperacao",SafeName(project.Name).Substring(0,Math.Min(50,SafeName(project.Name).Length))+"-"+BitConverter.ToString(hash.ComputeHash(Encoding.UTF8.GetBytes(key))).Replace("-","").Substring(0,12)+".circuito");}
  void StartAutosave(){autosave=new System.Windows.Forms.Timer{Interval=30000};autosave.Tick+=(s,e)=>{if(!dirty||revision==lastAutosave)return;try{project.Save(RecoveryFile());lastAutosave=revision;status.Text="Recuperação automática salva às "+DateTime.Now.ToString("HH:mm:ss");}catch(Exception ex){status.Text="Não foi possível salvar recuperação: "+ex.Message;}};autosave.Start();FormClosed+=(s,e)=>autosave.Dispose();}
  void Recover(){Directory.CreateDirectory(Path.Combine(userData,"recuperacao"));using(var d=new OpenFileDialog{Filter="Recuperação (*.circuito;*.bak)|*.circuito;*.bak|Todos os arquivos|*.*",InitialDirectory=Path.Combine(userData,"recuperacao"),Title="Abrir recuperação como uma nova cópia"}){if(d.ShowDialog(this)!=DialogResult.OK)return;RestoreRecovery(d.FileName);}}
  bool RestoreRecovery(string path){var restored=Project.Load(path);if(!ConfirmDiscard())return false;project=restored;board=project.Boards.FirstOrDefault();circuit=null;currentFile=null;Change();properties.SelectedObject=project;return true;}
  void BalancePhases(){var result=PhaseBalancing.Run(project);Change();MessageBox.Show("Distribuição monofásica por soma de correntes (heurística):\nL1: "+result.After[0].ToString("N2")+" A\nL2: "+result.After[1].ToString("N2")+" A\nL3: "+result.After[2].ToString("N2")+" A\nDesvio máximo da média: "+result.BeforePercent.ToString("N2")+"% → "+result.AfterPercent.ToString("N2")+"%\nFases travadas preservadas: "+result.Locked+"\n\nNão considera harmônicas, fasores ou corrente de neutro.","Balanceamento de fases");}
  void AddCapacitor(){if(board==null)throw new InvalidOperationException("Selecione um quadro.");using(var d=new Form{Text="Banco de capacitores",ClientSize=new Size(440,215),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog}){var value=new NumericUpDown{DecimalPlaces=2,Minimum=.01M,Maximum=1000000,Value=(decimal)Math.Max(.01,Math.Min(1000000,currentStudy.CapacitorKvar)),Location=new Point(260,25),Width=150};var label=new Label{Text="Potência capacitiva (kvar)",Location=new Point(20,28),Size=new Size(235,25)};var note=new Label{Text="A compensação será incluída em Q e nas correntes a montante.\nInforme o valor nominal do banco na tensão de operação.\nNão avalia harmônicas, ressonância, manobra ou transitórios.",Location=new Point(20,75),Size=new Size(400,75)};var apply=new Button{Text="Adicionar banco",Location=new Point(260,160),Size=new Size(150,34)};apply.Click+=(s,e)=>{AddCircuit();circuit.Name="Banco de capacitores";circuit.Kind="Banco capacitor";circuit.Phases=PhaseMode.Trifasico;circuit.PhaseLabel="ABC";circuit.Voltage=board.Voltage;circuit.PowerKw=0;circuit.ReactiveKvarOverride=-(double)value.Value;circuit.PowerFactor=1;circuit.DemandFactor=1;Change();d.DialogResult=DialogResult.OK;};d.Controls.AddRange(new Control[]{label,value,note,apply});d.ShowDialog(this);}}
  void MotorLoad(){if(circuit==null||board==null)throw new InvalidOperationException("Selecione um circuito para configurar o motor.");using(var form=new MotorStartingForm(project,board,circuit)){if(form.ShowDialog(this)==DialogResult.OK&&form.Changed){Change();tabs.SelectedTab=studyPage;}}}
 }
